function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const TODAY = '2026-09-15';
const CUTOFF = '2026-09-23';
const PRE = {};
['Body & Beyond','MonitorExam','Outlanders','ServeAmigo','SkillBytes','Fire Armor','Vira Jal','Washtro','Fuski.AI','Orbit AI','Koncite','Pixelence','Tronix.AI'].forEach(function (n) { PRE[nz(n)] = 1; });
const pipe = $('GET PIPELINE').first().json.values || [];
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
const ph = (pipe[0] || []).map(s);
const P = {};
['deal_id','startup','investor','owner','deal_shared','pause','next_action','next_due','notes'].forEach(function (n) { P[n] = ph.indexOf(n); if (P[n] < 0) { throw new Error('ABORT: PIPELINE missing ' + n); } });
const C = {}; ['pause','next_action','notes'].forEach(function (n) { C[n] = colLetter(P[n]); });
function d10(x) { const t = s(x); const m = t.match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? m[0] : ''; }
const updates = [], held = [], later = [], sent = [];
const why = 'HELD ' + TODAY + ' - angel + pre-revenue startup (Michele confirmed an angel by the user): memo and subject still carry the raise / pre-revenue wording. Release once the angel memo sanitiser is live.';
for (let r = 1; r < pipe.length; r++) { const row = pipe[r] || [];
  if (nz(row[P.investor]) !== 'michele') { continue; }
  if (!PRE[nz(row[P.startup])]) { continue; }
  const rn = r + 1; const id = s(row[P.deal_id]); const due = d10(row[P.next_due]);
  const rec = [rn, id, s(row[P.startup]), s(row[P.owner]), due];
  if (s(row[P.deal_shared]).toLowerCase() === 'yes') { sent.push(rec); continue; }
  if (s(row[P.pause]).toLowerCase() === 'yes') { continue; }
  if (due && due > CUTOFF) { later.push(rec); continue; }
  const note = s(row[P.notes]);
  updates.push({ range: 'PIPELINE!' + C.pause + rn, values: [['Yes']] });
  updates.push({ range: 'PIPELINE!' + C.next_action + rn, values: [['HOLD - angel memo sanitiser pending']] });
  updates.push({ range: 'PIPELINE!' + C.notes + rn, values: [[(note ? note + ' | ' : '') + why]] });
  held.push(rec); }
if (held.length > 25) { throw new Error('ABORT: ' + held.length + ' holds exceeds guard'); }
if (!updates.length) { updates.push({ range: 'PIPELINE!' + C.pause + '1', values: [['pause']] }); }
return [{ json: { summary: { held_now: held.length, due_later: later.length, already_sent: sent.length, cutoff: CUTOFF, cell_writes: updates.length },
  held: held, later: later, already_sent: sent, updates: updates } }];

